#pragma once

// Line break opportunities. The Annex 14 implementation is generated by script/PortUpstream.py.

#include <cstddef>
#include <cstdint>
#include <string>

namespace ipte {
enum struct BreakOption : uint8_t { MustBreak,
                                    AllowBreak,
                                    NoBreak,
                                    Undefined };

struct LineBreakConfig {
    bool UseUnicodeAnnex14{false};
    std::string BreakAfter{" \t{[("};
    std::string BreakBefore{"."};
    bool lb2{true}, lb3{true}, lb4{true}, lb5{true}, lb6{true}, lb7{true}, lb8{true}, lb8a{true}, lb9{true}, lb10{true}, lb11{true}, lb12{true}, lb12a{true}, lb13{true}, lb14{true}, lb15a{true}, lb15b{true}, lb15c{true}, lb15d{true}, lb16{true}, lb17{true}, lb18{true}, lb19{true}, lb19a{true}, lb20{true}, lb20a{true}, lb21{true}, lb21a{true}, lb21b{true}, lb22{true}, lb23{true}, lb23a{true}, lb24{true}, lb25{true}, lb26{true}, lb27{true}, lb28{true}, lb28a{true}, lb29{true}, lb30{true}, lb30a{true}, lb30b{true};

    bool operator==(const LineBreakConfig &) const = default;
};

// Sets `out[i]` to whether a break may follow glyph `i`. `size` must be at least 2.
void ClassifyAnnex14(const LineBreakConfig &config, const uint64_t *glyphs, size_t size, BreakOption *out);
} // namespace ipte
